<?php
namespace App\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;
class AuthController {public function show(){return view('auth.login');}public function login(Request $request){$credentials=$request->validate(['email'=>['required','email'],'password'=>['required']]);if(!Auth::attempt($credentials,$request->boolean('remember')))return back()->withErrors(['email'=>'The supplied login details are incorrect.'])->onlyInput('email');$request->session()->regenerate();return redirect()->intended($request->user()->is_super_admin?route('platform'):route('dashboard'));}public function logout(Request $request){Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect('/');}}
